packaging.version._deprecated:
def _deprecated(message: str) -> object:

    def decorator(func: Callable[([...], object)]) -> object:

        @functools.wraps(func)
        def wrapper(*args, **kwargs) -> object:
            warnings.warn(message, category=DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

packaging.metadata._parse_project_urls:
def _parse_project_urls(data: list[str]) -> dict[(str, str)]:
    """Parse a list of label/URL string pairings separated by a comma."""
    urls = {}
    for pair in data:
        (label, _, url) = (s.strip() for s in pair.partition(','))
        if label in urls:
            raise KeyError('duplicate labels in project urls')
        urls[label] = url
    return urls

packaging.specifiers._operator_cost:
def _operator_cost(op_entry: tuple[(CallableOperator, str, str)]) -> int:
    """Sort key for Cost Based Ordering of specifier operators in _filter_versions.

    Operators run sequentially on a shrinking candidate set, so operators that
    reject the most versions should run first to minimize work for later ones.

    Tier 0: Exact equality (==, ===), likely to narrow candidates to one version
    Tier 1: Range checks (>=, <=, >, <), cheap and usually reject a large portion
    Tier 2: Wildcard equality (==.*) and compatible release (~=), more expensive
    Tier 3: Exact !=, cheap but rarely rejects
    Tier 4: Wildcard !=.*, expensive and rarely rejects
    """
    (_, ver, op) = op_entry
    if op == '==':
        return (0 if not ver.endswith('.*') else 2)
    if op in ('>=', '<=', '>', '<'):
        return 1
    if op == '~=':
        return 2
    if op == '!=':
        return (3 if not ver.endswith('.*') else 4)
    if op == '===':
        return 0
    raise ValueError(f'Unknown operator: {op!r}')

packaging.pylock._get_sequence:
def _get_sequence(d: Mapping[(str, Any)], expected_item_type: type[_T], key: str) -> Sequence[_T] | None:
    """Get a list value from the dictionary and verify it's the expected items type."""
    if value := _get(d, Sequence, key) is None:
        return None
    if isinstance(value, (str, bytes)):
        raise PylockValidationError(f'Unexpected type {type(value).__name__} (expected Sequence)', context=key)
    for (i, item) in enumerate(value):
        if not isinstance(item, expected_item_type):
            raise PylockValidationError(f'Unexpected type {type(item).__name__} (expected {expected_item_type.__name__})', context=f'{key}[{i}]')
    return value

packaging.pylock._validate_hashes:
def _validate_hashes(hashes: Mapping[(str, Any)]) -> Mapping[(str, Any)]:
    if not hashes:
        raise PylockValidationError('At least one hash must be provided')
    if not all((isinstance(hash_val, str) for hash_val in hashes.values())):
        raise PylockValidationError('Hash values must be strings')
    return hashes

packaging.pylock._get_sequence_of_object:
def _get_sequence_of_objects(d: Mapping[(str, Any)], target_item_type: type[_FromMappingProtocolT], key: str) -> list[_FromMappingProtocolT] | None:
    """Get a list value from the dictionary and convert its items to a dataclass."""
    if value := _get_sequence(d, Mapping, key) is None:
        return None
    result: list[_FromMappingProtocolT] = []
    try:
        for item in value:
            typed_item = target_item_type._from_dict(item)
            result.append(typed_item)
    except Exception as e:
        raise PylockValidationError(e, context=f'{key}[{len(result)}]') from e
    return result

packaging.pylock._get:
def _get(d: Mapping[(str, Any)], expected_type: type[_T], key: str) -> _T | None:
    """Get a value from the dictionary and verify it's the expected type."""
    if value := d.get(key) is None:
        return None
    if not isinstance(value, expected_type):
        raise PylockValidationError(f'Unexpected type {type(value).__name__} (expected {expected_type.__name__})', context=key)
    return value

packaging.metadata._get_payload:
def _get_payload(msg: email.message.Message, source: bytes | str) -> str:
    """Get the body of the message."""
    if isinstance(source, str):
        payload = msg.get_payload()
        assert isinstance(payload, str)
        return payload
    else:
        bpayload = msg.get_payload(decode=True)
        assert isinstance(bpayload, bytes)
        try:
            return bpayload.decode('utf8', 'strict')
        except UnicodeDecodeError as exc:
            raise ValueError('payload in an invalid encoding') from exc

packaging.pylock._get_required_sequence_:
def _get_required_sequence_of_objects(d: Mapping[(str, Any)], target_item_type: type[_FromMappingProtocolT], key: str) -> Sequence[_FromMappingProtocolT]:
    """Get a required list value from the dictionary and convert its items to a
    dataclass."""
    if result := _get_sequence_of_objects(d, target_item_type, key) is None:
        raise _PylockRequiredKeyError(key)
    return result
